#version 300 es
precision highp float;
in vec2 vUv;
uniform sampler2D u_input;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_amount;
uniform float u_contrast;
out vec4 fragColor;

void main() {
  vec4 src = texture(u_input, vUv);
  float luma = dot(src.rgb, vec3(0.2126, 0.7152, 0.0722));
  vec3 shadows = vec3(0.0, 0.33, 0.38);
  vec3 highlights = vec3(1.0, 0.62, 0.32);
  vec3 graded = mix(shadows, highlights, smoothstep(0.05, 0.95, luma));
  vec3 toned = mix(src.rgb, src.rgb * 0.55 + graded * 0.6, clamp(u_amount, 0.0, 1.0));
  toned = (toned - 0.5) * max(u_contrast, 0.0) + 0.5;
  fragColor = vec4(clamp(toned, 0.0, 1.0), src.a);
}

#version 300 es
precision highp float;
in vec2 vUv;
uniform sampler2D u_input;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_fade;
uniform float u_warmth;
uniform float u_grain;
out vec4 fragColor;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {
  vec4 src = texture(u_input, vUv);
  vec3 c = mix(src.rgb, vec3(0.12) + src.rgb * 0.82, clamp(u_fade, 0.0, 1.0));
  c += vec3(0.06, 0.02, -0.05) * u_warmth;
  float n = hash(floor(vUv * u_resolution) + fract(u_time) * 97.0) - 0.5;
  c += n * u_grain * 0.25;
  vec2 d = vUv - 0.5;
  c *= 1.0 - dot(d, d) * 0.9;
  fragColor = vec4(clamp(c, 0.0, 1.0), src.a);
}

#version 300 es
precision highp float;
in vec2 vUv;
uniform sampler2D u_input;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_shift;
uniform float u_lines;
out vec4 fragColor;

void main() {
  float px = u_shift / max(u_resolution.x, 1.0);
  float wobble = sin(vUv.y * 40.0 + u_time * 6.0) * px * 0.5;
  float r = texture(u_input, vUv + vec2(px + wobble, 0.0)).r;
  vec4 g = texture(u_input, vUv);
  float b = texture(u_input, vUv - vec2(px - wobble, 0.0)).b;
  float scan = 0.5 + 0.5 * sin(vUv.y * u_resolution.y * 3.14159);
  vec3 c = vec3(r, g.g, b) * (1.0 - u_lines * 0.35 * scan);
  fragColor = vec4(clamp(c, 0.0, 1.0), g.a);
}
